    fn dump_cased_ranges() {
        let v = char::UNICODE_VERSION;
        let mut out = format!("UNICODE {}.{}.{}\n", v.0, v.1, v.2);
        let mut start: Option<u32> = None;
        let mut prev = 0u32;
        for c in (0x80u32..0x110000).filter_map(char::from_u32) {
            let cased = c.is_lowercase() || c.is_uppercase() || c.to_lowercase().ne(Some(c));
            let n = c as u32;
            if cased {
                if start.is_none() || prev + 1 != n {
                    if let Some(s) = start {
                        out.push_str(&format!("{s:X}-{prev:X}\n"));
                    }
                    start = Some(n);
                }
                prev = n;
            }
        }
        if let Some(s) = start {
            out.push_str(&format!("{s:X}-{prev:X}\n"));
        }
        panic!("{out}");
    }
}

