//! 단어 규칙(계약 2절)과 집계·정렬(계약 3절). 기준 구현의 tokenize, count_words 에 해당한다.

use std::collections::HashMap;

/// 단어 앞뒤에서 떼어 낼 문장 부호. 단어 가운데 있는 것은 남긴다 (don't, e-mail).
pub const PUNCTUATION: &str = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~“”‘’…·";

