            "{\"words\":5,\"unique\":3,\"top\":[{\"word\":\"rust\",\"count\":2}]}\n"
        );
        assert_eq!(
            format_json(&report(&[])),
            "{\"words\":5,\"unique\":3,\"top\":[]}\n"
        );
        let mut s = String::new();
        push_json_str(&mut s, "a\"b\\c\u{8}\u{c}\n\r\t\0\u{1b}\u{1f}\u{7f}\u{2028}한");
        assert_eq!(
            s,
            "\"a\\\"b\\\\c\\b\\f\\n\\r\\t\\u0000\\u001b\\u001f\u{7f}\u{2028}한\""
        );
    }
}

